# Standard library
import uuid

# Third-party
from sqlalchemy import func
from sqlalchemy.orm import Mapped, mapped_column

# Local application
from app.core.base import Base, ReferenceWithRankMixin


class CoreRefDifficultyLevel(Base, ReferenceWithRankMixin):
    __tablename__ = "core_ref_difficulty_level"

    id: Mapped[uuid.UUID] = mapped_column(
        primary_key=True,
        server_default=func.gen_random_uuid(),
        comment=(
            "Primary key UUID, auto-generated by the database. Uniquely "
            "identifies a general difficulty level such as Easy, Moderate, "
            "Difficult, or Expert."
        ),
    )
